"use strict";(self.webpackChunkmy_website=self.webpackChunkmy_website||[]).push([[8130],{7735:e=>{e.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"robocon-orc-national-finals-2025-2026","metadata":{"permalink":"/blog/robocon-orc-national-finals-2025-2026","editUrl":"https://github.com/ACLAB-HCMUT/ACLAB-HCMUT.github.io/tree/main/blog/2026-06-09-robocon-orc-national-finals.md","source":"@site/blog/2026-06-09-robocon-orc-national-finals.md","title":"Robocon ORC National Finals 2025\u20132026 draws nearly 200 teams","description":"The Robocon ORC National Finals 2025\u20132026 wrapped up on June 6\u20137, 2026 at the","date":"2026-06-09T00:00:00.000Z","tags":[{"inline":false,"label":"Competition","permalink":"/blog/tags/competition","description":"Competitions and contests"},{"inline":false,"label":"News","permalink":"/blog/tags/news","description":"Lab news and announcements"}],"readingTime":0.98,"hasTruncateMarker":true,"authors":[{"name":"ACLAB","title":"Advanced Computing Lab, HCMUT","url":"https://github.com/ACLAB-HCMUT","page":{"permalink":"/blog/authors/aclab"},"socials":{"github":"https://github.com/ACLAB-HCMUT"},"imageURL":"https://github.com/ACLAB-HCMUT.png","key":"aclab"}],"frontMatter":{"slug":"robocon-orc-national-finals-2025-2026","title":"Robocon ORC National Finals 2025\u20132026 draws nearly 200 teams","authors":["aclab"],"tags":["competition","news"]},"unlisted":false,"nextItem":{"title":"Seminar: Edge AI for real-time visual inspection","permalink":"/blog/seminar-edge-ai-inspection"}},"content":"The **Robocon ORC National Finals 2025\u20132026** wrapped up on **June 6\u20137, 2026** at the\\r\\nHo Chi Minh City University of Technology and Education, bringing together **nearly 200 teams\\r\\nfrom more than 100 schools** across Vietnam \u2014 a highlight of the country\'s growing STEM robotics\\r\\ncommunity.\\r\\n\\r\\n\x3c!-- truncate --\x3e\\r\\n\\r\\n## At a glance\\r\\n\\r\\n- **When:** June 6\u20137, 2026\\r\\n- **Where:** Ho Chi Minh City University of Technology and Education\\r\\n- **Scale:** ~200 teams from 100+ schools nationwide, from primary school through university\\r\\n- **Format:** multiple divisions by age/experience; teams were judged on robot assembly and\\r\\n  programming, tactics, on-the-spot problem solving, and teamwork\\r\\n- **Season:** the finals capped a year-long path of online rounds and regional tournaments\\r\\n\\r\\nThe event was organized by the Institute for School Design Research (under the Ministry of\\r\\nEducation and Training), co-hosted with Phan Thiet University, and sponsored by **OhStem\\r\\nEducation** \u2014 one of [ACLAB\'s partners](/partners) in STEM and robotics competitions \u2014 together\\r\\nwith Lidinco.\\r\\n\\r\\n:::note Why we\'re sharing this\\r\\nACLAB works with OhStem on hands-on robotics and competition activities. Events like this grow\\r\\nthe talent pipeline we love to see join the lab. Interested in building competition robots?\\r\\n[Join ACLAB](/join).\\r\\n:::\\r\\n\\r\\nSource: [orc.vn](https://www.orc.vn/chung-ket-robocon-orc-toan-quoc-2025-2026-quy-tu-gan-200-doi-thi-tren-ca-nuoc/)"},{"id":"seminar-edge-ai-inspection","metadata":{"permalink":"/blog/seminar-edge-ai-inspection","editUrl":"https://github.com/ACLAB-HCMUT/ACLAB-HCMUT.github.io/tree/main/blog/2026-05-20-seminar-edge-ai.md","source":"@site/blog/2026-05-20-seminar-edge-ai.md","title":"Seminar: Edge AI for real-time visual inspection","description":"This month\'s lab seminar covers deploying quantized vision models on embedded","date":"2026-05-20T00:00:00.000Z","tags":[{"inline":false,"label":"Seminar","permalink":"/blog/tags/seminar","description":"Talks and seminars"},{"inline":false,"label":"News","permalink":"/blog/tags/news","description":"Lab news and announcements"}],"readingTime":0.39,"hasTruncateMarker":true,"authors":[{"name":"ACLAB","title":"Advanced Computing Lab, HCMUT","url":"https://github.com/ACLAB-HCMUT","page":{"permalink":"/blog/authors/aclab"},"socials":{"github":"https://github.com/ACLAB-HCMUT"},"imageURL":"https://github.com/ACLAB-HCMUT.png","key":"aclab"}],"frontMatter":{"slug":"seminar-edge-ai-inspection","title":"Seminar: Edge AI for real-time visual inspection","authors":["aclab"],"tags":["seminar","news"]},"unlisted":false,"prevItem":{"title":"Robocon ORC National Finals 2025\u20132026 draws nearly 200 teams","permalink":"/blog/robocon-orc-national-finals-2025-2026"},"nextItem":{"title":"ACLAB team reaches national robotics competition finals","permalink":"/blog/robotics-competition-finals"}},"content":"This month\'s lab seminar covers **deploying quantized vision models on embedded\\naccelerators** for real-time quality control on the factory floor.\\n\\n\x3c!-- truncate --\x3e\\n\\n## Topics\\n\\n- Model quantization and pruning for edge devices\\n- Running inference on Jetson with TensorRT\\n- Measuring latency, throughput and power on-device\\n- A walkthrough of our visual-inspection project pipeline\\n\\nThe session is open to all lab members and interested students. Slides and demo\\ncode will be shared in the [Knowledge Base](/docs/intro) afterwards."},{"id":"robotics-competition-finals","metadata":{"permalink":"/blog/robotics-competition-finals","editUrl":"https://github.com/ACLAB-HCMUT/ACLAB-HCMUT.github.io/tree/main/blog/2026-04-10-robotics-competition.md","source":"@site/blog/2026-04-10-robotics-competition.md","title":"ACLAB team reaches national robotics competition finals","description":"Our autonomous AGV team reached the finals of a national robotics competition","date":"2026-04-10T00:00:00.000Z","tags":[{"inline":false,"label":"Competition","permalink":"/blog/tags/competition","description":"Competitions and contests"},{"inline":false,"label":"News","permalink":"/blog/tags/news","description":"Lab news and announcements"}],"readingTime":0.355,"hasTruncateMarker":true,"authors":[{"name":"ACLAB","title":"Advanced Computing Lab, HCMUT","url":"https://github.com/ACLAB-HCMUT","page":{"permalink":"/blog/authors/aclab"},"socials":{"github":"https://github.com/ACLAB-HCMUT"},"imageURL":"https://github.com/ACLAB-HCMUT.png","key":"aclab"}],"frontMatter":{"slug":"robotics-competition-finals","title":"ACLAB team reaches national robotics competition finals","authors":["aclab"],"tags":["competition","news"]},"unlisted":false,"prevItem":{"title":"Seminar: Edge AI for real-time visual inspection","permalink":"/blog/seminar-edge-ai-inspection"}},"content":"Our autonomous AGV team reached the **finals of a national robotics competition**\\nwith a LiDAR-based navigation stack designed and built entirely in the lab.\\n\\n\x3c!-- truncate --\x3e\\n\\n## Highlights\\n\\n- Differential-drive AGV with custom motor-driver PCBs\\n- LiDAR SLAM and ROS 2 navigation\\n- Real-time obstacle avoidance and path planning\\n\\nCongratulations to the team! The platform continues as one of our active\\n[projects](/projects). Want to build the next one? [Join ACLAB](/join)."}]}}')}}]);